// Generated by scripts/skill/generate-fix-sections.mjs. Do not edit.

export const FIX_SECTIONS: Readonly<Record<string, string>> = {
  'references/audit.md#common-replacements':
    "## Common replacements\n\n| Current pattern                                                      | Replace with                                                                                                                                                                                       |\n| -------------------------------------------------------------------- | -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Manual `requestAnimationFrame` loop + `cancelAnimationFrame` cleanup | CSS/WAAPI if browser-animatable; `useLoop` (DOM) or `useCanvas` (canvas) when frames require live JS                                                                                               |\n| `requestAnimationFrame` without `cancelAnimationFrame`               | Same tier decision, plus phase cleanup is automatic when a loop is required                                                                                                                        |\n| `new IntersectionObserver` for visibility                            | Use `useSight` or `useLifecycle` only if they support the same elements and data; otherwise keep it only after checking how removed elements are unobserved and who disconnects it                 |\n| `new IntersectionObserver` for scroll progress                       | Use `useScrollProgress` only if it reports the same ratio for every element; otherwise keep it only after checking how removed elements are unobserved and who disconnects it                      |\n| `new ResizeObserver` for dimensions                                  | Use `useSize` only if it watches the same element and provides the needed data; otherwise keep it only after checking how removed elements are unobserved and who disconnects it                   |\n| Raw `MutationObserver` with reflow reads in callback                 | `useMutation` (rAF-batched, visibility-aware)                                                                                                                                                      |\n| `MutationObserver` on `style`/`attributes` to track size or position | `useSize` (ResizeObserver) / `useSight` (IO); reserve MO for `childList`                                                                                                                           |\n| Multiple `MutationObserver` on `<html>` for class changes            | Single `useMutation` with coalesced callback                                                                                                                                                       |\n| `matchMedia('(prefers-reduced-motion: reduce)')`                     | `prefersReducedMotion()` or rely on phase hooks (automatic)                                                                                                                                        |\n| `matchMedia(query)` + change listener                                | `useMediaQuery` (pooled MQL, reactive)                                                                                                                                                             |\n| `useState` + `requestAnimationFrame` for tween                       | `useTween`                                                                                                                                                                                         |\n| `useState` inside rAF for DOM writes                                 | `useLoop` with ref-based writes                                                                                                                                                                    |\n| `getBoundingClientRect()` in animation                               | `useSize` (async, no reflow)                                                                                                                                                                       |\n| `getBoundingClientRect()` in a `pointermove` handler                 | `usePointer` (one rAF-batched `getBoundingClientRect` per frame, not per event)                                                                                                                    |\n| SVG transform/geometry attributes written during animation           | CSS `transform`/`opacity` on an HTML wrapper; verify browser support and `transform-box` before transforming an SVG element directly                                                               |\n| `transitionend` listener for unmount                                 | `<Presence>` or `usePresence`                                                                                                                                                                      |\n| Multiple independent rAF loops                                       | Multiple `useLoop` instances (shared clock)                                                                                                                                                        |\n| CSS-only animation that's working fine                               | No change. Don't add JS where it's not needed.                                                                                                                                                     |\n| Hand-wired IO + visibilitychange + reduced motion → boolean          | `useLifecycle` (single hook, same signals, pooled IO)                                                                                                                                              |\n| `getBoundingClientRect()` for initial in-view check                  | Trust IO (one-frame delay is invisible) or `rootMargin`                                                                                                                                            |\n| Permanent `will-change-transform`                                    | Toggle with animation state; or remove entirely for JS loops                                                                                                                                       |\n| Tailwind `transition-all`                                            | Name the transitioned properties: `transition-colors`, `transition-transform`, `transition-[color,box-shadow]`                                                                                     |\n| `setTimeout`/`setInterval` for timed animation sequences             | CSS/WAAPI + `useLifecycle` when predetermined and keyframe-friendly; `useLoop` with elapsed-time steps only when JavaScript must own the timeline (see [timed-sequences.md](./timed-sequences.md)) |\n| `useRef(v)` + unconditional `ref.current = v` on every render        | `useSyncedRef(v)` (dedup, the raw pattern is correct, only verbose)                                                                                                                                |\n| `useCallback` with empty deps calling through a ref                  | `useStableCallback(fn)` (dedup, the same idiom in one line)                                                                                                                                        |\n| Heavy panel always mounted with `display:none`                       | Conditional rendering + `Presence` + `useWhenIdle` prefetch                                                                                                                                        |\n| N components with bare `window.addEventListener('resize', ...)`      | `useSize` or `useMediaQuery` (pooled observers, no raw listeners)                                                                                                                                  |\n| `scroll` handler reading `scrollWidth`/`clientWidth`                 | `useScroll` (rAF-batched offset + progress; geometry cached, read only on resize, not per event)                                                                                                   |\n| Global `body:has(...)` in stylesheet                                 | Scope with a subtree-scoped `<style>` or data-attribute pattern                                                                                                                                    |\n| Large list without `content-visibility`                              | `Defer` with `as` prop for semantic elements                                                                                                                                                       |\n| `WhenVisible`/`WhenIdle` with no `fallback`                          | Verify the final in-flow footprint; reserve it through the wrapper, parent, or `fallback` when nonzero                                                                                             |\n| `@keyframes` animating `height`/`width`/`top`/`left`                 | Keyframe `transform`/`opacity`; for expand/collapse use `grid-template-rows` transitions or measure once with `useSize`                                                                            |\n\n### Outside React\n\nEvery row above names a hook because React is the common case, and recommending a hook to a consumer who is not using React is not a recommendation. The scanner reads `.js`/`.ts` regardless of framework, so check what the file is before you answer. Outside React — vanilla, Vue, Svelte, Astro islands, web components — substitute the core primitive, which carries the same lifecycle guarantees and differs only in binding:\n\n| Hook                               | Core primitive                         |\n| ---------------------------------- | -------------------------------------- |\n| `useLoop`, `useCanvas`, `useTween` | `createLoop`, `createTicker`           |\n| `useSight`                         | `createSight`                          |\n| `useLifecycle`                     | `createLifecycle`                      |\n| `usePointer`                       | `createPointer`                        |\n| `useScroll`, `useScrollProgress`   | `createScroll`, `createScrollProgress` |\n| `useMutation`                      | `createMutation`                       |\n| `useRenderState`                   | `createRenderState`                    |\n| `useDevicePixelRatio`              | `createDevicePixelRatio`               |\n| `usePrefersReducedMotion`          | `prefersReducedMotion()`               |\n| `useIdle`, `useWhenIdle`           | `whenIdle`                             |\n\n`useSize`, `useMediaQuery`, and `useContainerQuery` have no core export: outside React, use `createLifecycle` for the visibility half and the pooled observers behind it. The composition components (`Presence`, `Swap`, `WhenVisible`, `WhenIdle`, `Defer`) are React-only by nature; outside React, recommend the equivalent pattern (a state class toggled on `transitionend`, or `content-visibility`) rather than naming a component the consumer cannot import.",
  'references/audit.md#step-15-css-loading-and-architecture-pass':
    "## Step 1.5: CSS, loading, and architecture pass\n\nRun this alongside the JS scan, before classifying. The scanner automates the CSS/architecture signals marked below; the rest are manual inspection.\n\n### CSS/DOM-scale checks\n\n- **Non-compositor animation** (scanner: `non-compositor-animation` and `keyframes-layout-animation` for CSS, `tailwind-transition-all` for JSX). `transition: all`, a bare-duration shorthand (`transition: 0.3s`), or transitioning/keyframing layout properties (`width`/`height`/`top`/`left`/`margin`) animates off the compositor: layout and paint every frame. Prefer `transform`/`opacity`.\n- **Global `:has()` selectors** (scanner: `global-has-selector`). `body:has(...)`, `html:has(...)`, `:root:has(...)`, or `*:has(...)` in a global stylesheet can trigger broad style invalidation; cost scales with the argument selector and subtree size. Scope the rule to a subtree or replace with a data attribute.\n- **Missing `content-visibility`** (manual). Large repeated lists (`.map()` returning many items) without `content-visibility: auto` or `Defer` pay full off-screen style/layout cost.\n- **Permanent `will-change`** (scanner: `permanent-will-change` for CSS, `tailwind-permanent-will-change` for JSX). `will-change` that is never toggled wastes GPU memory when idle.\n- **SVG SMIL animation** (scanner: `svg-smil-animation`). SMIL uses the SVG root timeline, not CSS `@keyframes` or `animation-play-state`. Review static reduced-motion output, root lifecycle ownership, and delayed-start cleanup ([smil.md](./smil.md)).\n\n### Loading checks (manual)\n\n- **Heavy static imports in always-mounted subtrees.** Top-level imports of heavy packages (markdown renderers, syntax highlighters, animation libraries) in components that mount on every route.\n- **`display:none` as a close mechanism.** Components hidden with `display:none`/`visibility:hidden` instead of unmounting keep all JS, observers, and subscriptions running.\n\n### Architecture checks\n\n- **Redundant observers** (scanner: `redundant-mutation-observers`). Multiple `new MutationObserver` calls targeting `<html>`/`document.documentElement`, each firing on class changes; coalesce into one `useMutation`.\n- **Bare window listeners with layout reads** (scanner: `bare-window-listener`). Components attaching `addEventListener('resize'|'scroll', ...)` with `getBoundingClientRect`/`offset*` reads in the handler. Replace size reads with pooled `useSize`/`useMediaQuery`, and scroll-position reads (`scrollLeft`/`scrollWidth`) with `useScroll`.\n- **Pointer handlers reading layout** (scanner: `pointer-listener-layout-read`). A `pointermove`, `mousemove`, or `touchmove` handler that reads layout can force a reflow on every event, and move events may arrive faster than frames. The scanner checks raw listeners and lowercase-tag JSX props (`onPointerMove`, `onMouseMove`, and `onTouchMove`). It follows inline handlers and one local function, arrow, or `useCallback` binding, but not helper calls. Follow synchronous same-file helpers by hand. Use `usePointer` when the handler needs element-relative coordinates, but keep gesture-library and renderer event behavior.\n- **Raw IO/RO cleanup** (scanner: `raw-io`, `raw-ro`). A raw observer skips phase's shared pool but does not prove a leak. Check how many elements it watches, how it uses each observer entry, how elements are removed, and who disconnects it. Replace it only if a phase API supports the same behavior. One shared observer may remain simplest for a changing set of elements or custom entry data. Fix missing cleanup, one observer per item, duplicate subscriptions, and simple single-element wiring that a phase API already covers.\n- **Reduced motion handled by a parent** (scanner: `reduced-motion-ignored`). Check the matched child's parent. `'ignore'` may remain when the parent responds to preference changes, does not render the animated child while reduced motion is on, and shows the same information without motion. A one-time preference check, incomplete fallback, or unchecked consumer leaves the finding unresolved.\n- **External renderers.** Keep renderer creation and cleanup with the component that owns it. Keep `useLifecycle` for start, pause, and resume. If the renderer accepts updates without rebuilding, use `useSize({ ref, onResize })` for size, `usePointer({ ref, onPointer, visibility: 'ignore', enabled: isActive })` for pointer input, and `useDevicePixelRatio` for pixel density. Keep the renderer instead of adding a generic phase wrapper.\n- **State in frame callbacks** (scanner: `setstate-in-raf`, `setstate-in-ontick`). Check whether the update can run every frame or exactly once. A one-time update may remain if the callback blocks repeats and also disables the loop or stops scheduling rAF. Move values that change every frame to refs or the DOM.\n- **Raw `matchMedia` subscriptions** (scanner: `raw-matchmedia`). Hand-rolled MediaQueryList listeners duplicate what the pooled `useMediaQuery`/`usePrefersReducedMotion` provide.\n\n### Opportunity checks (scanner-silent)\n\nA clean scan means no anti-pattern candidates, not no opportunities: the scanner finds what is wrong, this pass finds what phase would make better. Walk the entry points from Step 0 and check for:\n\n- **Long-running or infinite CSS animations** (spinners, marquees, animated gradients) with no visibility gating. Even with reduced-motion handled, they burn CPU/GPU off-screen and in background tabs. → `useLifecycle` toggling `animation-play-state` (see [decision-guide.md](./decision-guide.md)).\n- **`transitionend`/`animationend` listeners that mount, unmount, or replace content.** Use `Presence` or `Swap`. Keep a listener that only records completion when retry or recovery requires every layer to stay mounted.\n- **Eagerly mounted non-critical UI** (below-fold sections, chat widgets, pickers, heavy modals). → `Defer` (SSR-safe default) or `WhenVisible`/`WhenIdle`, subject to the [Step 2.5](#step-25-verify-the-blast-radius) semantics rules.\n- **Finite `setTimeout` chains sequencing UI states.** The scanner reports recurring timers near animation vocabulary, but it does not report a chain of one-shot timeouts even when the chain drives visible motion. → CSS/WAAPI when the sequence is predetermined and keyframe-friendly; `useLoop` with `frame.elapsed` only when JavaScript must own the steps ([timed-sequences.md](./timed-sequences.md)).\n- **Phase loops replaying a predetermined timeline** (scanner: `phase-loop-browser-keyframes`). Verify that output depends only on elapsed time, can be expressed as browser-animatable keyframes, and requires no per-frame JS side effects. → CSS/WAAPI for playback, with `useLifecycle` as the visibility gate. Also verify that first-paint CSS matches keyframe zero and reduced motion renders a meaningful static state instead of pausing there.\n- **Scroll listeners doing position math without layout reads.** The scanner only flags handlers that read layout. → `useScroll`.\n- **One-shot `matchMedia(...).matches` reads.** The scanner only flags a MediaQueryList something subscribes to, so a snapshot is silent. Check whether the value has to react: a snapshot read once at mount is stale after a theme change, a rotation, or a move to another monitor. → `useMediaQuery` when it must react, `prefersReducedMotion()` for a deliberate one-time read.\n- **A canvas or bitmap sized from `devicePixelRatio` once.** Reading it at mount and never again leaves the surface blurry after a browser zoom or a move to a different-density monitor, which reads as a rendering bug rather than a perf one. → `useDevicePixelRatio` ([use-device-pixel-ratio.md](./use-device-pixel-ratio.md)).\n- **JS still running inside a skipped `content-visibility: auto` subtree.** Containment stops rendering work, not timers, observers, or loops; the subtree keeps computing for content the browser is not painting. → `useRenderState` to observe the skipped state and pause ([use-render-state.md](./use-render-state.md)).\n- **A ResizeObserver used to pick a layout, not to measure one.** Width compared against breakpoints to choose a variant is a container query wearing an observer's clothes. → `useContainerQuery` ([use-container-query.md](./use-container-query.md)).\n\nEach opportunity still goes through Step 2 classification and Step 2.5 blast-radius verification like any scanner candidate; \"no change\" remains a valid verdict when the current code is already the cheapest sufficient tier.\n\n### Classification ladders\n\nIn addition to the animation ladder (`CSS → useTween → phase → external library`), classify loading and containment candidates:\n\n**Loading ladder** (prefer the cheapest tier):\n\n```\nStatic import  →  next/dynamic  →  WhenVisible + dynamic  →  useWhenIdle prefetch\n```\n\n**Containment ladder** (prefer the cheapest tier):\n\n```\nCSS content-visibility  →  Defer  →  WhenVisible / WhenIdle  →  conditional unmount\n```",
  'references/decision-guide.md#browser-driven-timelines-css-or-waapi':
    "#### Browser-driven timelines: CSS or WAAPI\n\nBefore choosing `useLoop`, ask whether the browser can own the future frames:\n\n- Progress comes from a browser-owned document, scroll, or view timeline instead of an author-owned per-frame callback.\n- Each target's values can be represented as CSS-animatable keyframes, ideally `transform` and `opacity`. For a document-time sequence, the targets and keyframes are known when playback starts.\n- No JavaScript side effect is required on every frame.\n\nIf all three are true, prefer CSS for static keyframes and WAAPI for generated or imperatively controlled keyframes. Use `useLifecycle` only as the _when_ layer when playback must pause off-screen or for reduced motion. Do not keep `useLoop` merely because the sequence has many steps or depends on elapsed time.",
  'references/decision-guide.md#common-mistakes':
    "## Common mistakes\n\n- **Recommending phase for a CSS-only animation.** If `@starting-style` + `transition` or a CSS `animation` handles the enter/exit, don't add JS. Phase is for when CSS genuinely can't do it.\n- **Using `useLoop` when `useTween` is sufficient.** If you're animating one value into render output and the component is cheap, `useTween` has a smaller API surface and bundle. `useLoop` is for when you need ref-based DOM writes or many values.\n- **Using `useLifecycle` expecting it to drive frames.** It only gives you an active/paused signal. CSS, WAAPI, or an external renderer must own playback; use `useLoop` or `useCanvas` only when phase must drive the clock.\n- **Forgetting that `createLoop` has no `pause()`/`resume()`.** It's signal-driven (visibility, reduced motion, quality). For manual control, use `createLifecycle` which exposes `pause()`/`resume()`, or use the React hook's `enabled` prop.\n- **Reaching for an external library for enter/exit transitions.** `Presence`, `Swap`, and `WhenVisible` handle mount/unmount with CSS `@starting-style` + `transitionend`. You don't need a library for this.\n- **Confusing `useScrollProgress` with `useScroll`.** The first is a viewport visibility ratio (reveals, parallax); the second is a scroll container's own offset (scrollbars, carousels). See the \"Which scroll primitive?\" table above.\n- **Using `useLifecycle` + `setTimeout`/`setInterval` to build timed animation sequences.** `useLifecycle` only provides visibility signals. Use CSS/WAAPI when the sequence is predetermined and keyframe-friendly, or `useLoop` with `frame.elapsed` when JavaScript must own the steps. See [timed-sequences.md](./timed-sequences.md).\n- **Using `createLoop` / `createTicker` / `createLifecycle` in React when the hook would work.** Prefer the hook equivalents (`useLoop`, `useCanvas`, `useLifecycle`) — they manage refs, teardown, and `enabled` automatically. Reach for core primitives only when the hook doesn't fit: custom hooks composed from multiple primitives, `AbortController`-based teardown, or imperative managers that own their lifecycle.",
  'references/decision-guide.md#tier-1-browser-driven-css-or-waapi':
    "### Tier 1: Browser-driven (CSS or WAAPI)\n\nUse CSS when the animation:\n\n- Is triggered by a state class, pseudo-class, or attribute change (`:hover`, `data-*`, `[open]`)\n- Is a pure enter/exit transition (`@starting-style` + `transition`, or `animation`)\n- Uses View Transitions API for route/page changes\n\nExamples: fade in on mount, slide on hover, opacity toggle, cross-fade between routes.\n\nUse WAAPI (`Element.animate`) when the complete, browser-animatable timeline is known at start but its keyframes are generated from runtime data or need imperative `play()`, `pause()`, or `currentTime` control. CSS and WAAPI both let the browser sample keyframes without an author-owned per-frame callback. `transform` and `opacity` can then run on the compositor; other properties may still require style, layout, or paint.\n\n#### Browser-driven timelines: CSS or WAAPI\n\nBefore choosing `useLoop`, ask whether the browser can own the future frames:\n\n- Progress comes from a browser-owned document, scroll, or view timeline instead of an author-owned per-frame callback.\n- Each target's values can be represented as CSS-animatable keyframes, ideally `transform` and `opacity`. For a document-time sequence, the targets and keyframes are known when playback starts.\n- No JavaScript side effect is required on every frame.\n\nIf all three are true, prefer CSS for static keyframes and WAAPI for generated or imperatively controlled keyframes. Use `useLifecycle` only as the _when_ layer when playback must pause off-screen or for reduced motion. Do not keep `useLoop` merely because the sequence has many steps or depends on elapsed time.",
  'references/performance-recipes.md#recipe-collapse-an-observer-storm-on-html':
    "## Recipe: collapse an observer storm on `<html>`\n\n**Scenario:** a theme switcher or third-party library writes a class to `<html>` and several components each spin up their own `MutationObserver` to react. Flagged by the scanner's `redundant-mutation-observers` signal.\n\n```tsx\nimport { useState, useRef } from 'react';\nimport { useMutation } from 'phase/react';\n\nfunction useThemeClass() {\n  const [theme, setTheme] = useState('light');\n  const htmlRef = useRef(document.documentElement);\n\n  useMutation({\n    ref: htmlRef,\n    mutation: { attributes: true, attributeFilter: ['class'] },\n    onMutations: () => {\n      const cl = document.documentElement.classList;\n      setTheme(cl.contains('dark') ? 'dark' : 'light');\n    },\n    visibility: 'ignore',\n  });\n\n  return theme;\n}\n```\n\n**Why this works:** one `useMutation` coalesces all class mutations into a single rAF callback, and many components can consume its result through one shared hook. A narrow `attributeFilter` on a single element (not a subtree) keeps the callback count low. `visibility: 'ignore'` because `<html>` is never meaningfully off-screen: the default `'pause'` would add an `IntersectionObserver` + `visibilitychange` subscription that here is pure overhead, and would stop tracking when the tab is backgrounded.\n\n**What it replaces:** N separate `MutationObserver` instances on `<html>`, each firing synchronously per class change.",
  'references/performance-recipes.md#recipe-collapse-n-bare-window-resize-listeners-into-one-pooled-observer':
    "## Recipe: collapse N bare `window` resize listeners into one pooled observer\n\n**Scenario:** several components each attach a `window` `resize` listener whose handler reads layout (`getBoundingClientRect`, `offsetWidth`) to react to their own size. Flagged by the scanner's `bare-window-listener` signal.\n\n```tsx\nimport { useSize } from 'phase/react';\n\nfunction Sidebar() {\n  const { ref, size } = useSize<HTMLElement>();\n  const collapsed = (size?.width ?? Infinity) < 240;\n  return <aside ref={ref} data-collapsed={collapsed || undefined} />;\n}\n```\n\n**Why this works:** `useSize` reads from the shared `ResizeObserver` singleton: async, compositor-aligned, no `getBoundingClientRect`. Twenty components share one observer. A bare `window` resize listener with a layout read forces a synchronous reflow on every resize event, once per component, and fires even when the element's own size did not change.\n\n**What it replaces:** N components each calling `window.addEventListener('resize', ...)` with a `getBoundingClientRect`/`offset*` read in the handler. For viewport-level breakpoints (not element size), use `useMediaQuery` instead. For scroll position (custom scrollbars, carousels), use `useScroll`, not a bare `scroll` listener that reads `scrollWidth`/`clientWidth`.",
  'references/performance-recipes.md#recipe-delete-a-global-has-rule':
    "## Recipe: delete a global `:has()` rule\n\n**Scenario:** a global stylesheet contains `body:has(.modal-open) { overflow: hidden; }`, so the style engine re-checks the `:has()` condition on any DOM/class change that could affect its argument, causing broad, hard-to-scope invalidation. Flagged by the scanner's `global-has-selector` signal.\n\n```tsx\nimport { useEffect } from 'react';\n\n// No phase primitive needed: the fix is to delete the global rule.\nfunction ModalOverflowGuard({ open }: { open: boolean }) {\n  useEffect(() => {\n    if (open) document.body.style.overflow = 'hidden';\n    else document.body.style.overflow = '';\n    return () => {\n      document.body.style.overflow = '';\n    };\n  }, [open]);\n\n  return null;\n}\n```\n\n**Why this works:** a direct `style` write on `body` bypasses the selector engine entirely, so there is no global `:has()` rule to invalidate against.\n\n**What it replaces:** `body:has(.modal-open) { overflow: hidden; }` in a global stylesheet, whose invalidation set spans the whole document and is re-checked whenever a mutation could affect the argument.",
  'references/performance.md#never-drive-layout-from-a-mutationobserver':
    "### Never drive layout from a `MutationObserver`\n\nNever read layout inside a `MutationObserver` callback. The callback fires after the DOM has mutated but before the browser lays it out again, so any layout read forces a synchronous reflow to resolve the dirty layout, and it repeats on every callback:\n\n- `getBoundingClientRect()`\n- `offsetWidth`, `offsetHeight`\n- `scrollWidth`, `scrollHeight`, `scrollTop`, `scrollLeft`\n- `clientWidth`, `clientHeight`\n- `getComputedStyle()`\n\nObserving `attributes` (especially `attributeFilter: ['style']`) with `subtree: true` to react to size or position is the most expensive case. JS-driven animation libraries (motion, react-spring) rewrite inline styles every frame, so the observer reflows once per mutation per frame across the whole subtree.\n\n**Don't:**\n\n```ts\nconst mo = new MutationObserver(() => {\n  const { scrollHeight, clientHeight } = el; // forced reflow, on every style mutation\n  thumb.style.height = `${(clientHeight / scrollHeight) * trackH}px`;\n});\nmo.observe(el, { subtree: true, attributes: true, attributeFilter: ['style'] });\n```\n\n**Do:** React to size with `ResizeObserver` (`useSize`) and to visibility with `IntersectionObserver` (`useSight`). Both are async, compositor-aligned, and never force reflow. Reach for `MutationObserver` only for structural changes (`childList`). If you must read layout in response, coalesce callbacks into one `requestAnimationFrame` and separate all reads from all writes.\n\n```ts\nconst { ref, size } = useSize(); // async, compositor-aligned, no layout read\n```",
  'references/performance.md#never-write-repeated-state-inside-ontick--draw':
    "### Never write repeated state inside `onTick` / `draw`\n\nA state update in a recurring callback can make React re-render on every tick and compete with the animation. Check whether it repeats or records one final state change. Write repeated values to refs or the DOM.\n\n**Do:**\n\n```ts\nonTick: (frame) => {\n  ref.current.style.opacity = String(clamp01(frame.elapsed / 1000));\n};\n```\n\n**Don't:**\n\n```ts\nonTick: (frame) => {\n  setOpacity(clamp01(frame.elapsed / 1000)); // may re-render on every tick\n};\n```\n\nA one-time state update is allowed if the callback first sets a guard and then disables the phase loop or stops scheduling raw rAF. The guard prevents another update before React commits and tears down the hook. Use this only to record completion or recovery, not values that change every frame. See [Finite sequence](./timed-sequences.md#finite-sequence-stop-after-the-last-step). Use `useTween` when one value intentionally drives React rendering.",
  'references/performance.md#no-forced-reflows-in-animation-paths':
    "### No forced reflows in animation paths\n\nLayout-triggering APIs force the browser to synchronously compute layout before returning a value. Inside a 60fps loop, this means the browser performs a full style-recalc + layout pass _every single frame_ before your animation can proceed. This is the exact opposite of compositor-aligned animation. Never call these inside or near `onTick`:\n\n- `getBoundingClientRect()`\n- `offsetWidth`, `offsetHeight`, `offsetTop`, `offsetLeft`\n- `scrollWidth`, `scrollHeight`, `scrollTop`, `scrollLeft`\n- `getComputedStyle()`\n- `clientWidth`, `clientHeight`\n\n**Do:** Use `useSize` (ResizeObserver, async, compositor-aligned).\n\n**Don't:**\n\n```ts\nonTick: () => {\n  const rect = el.getBoundingClientRect(); // FORCES SYNCHRONOUS LAYOUT\n  el.style.transform = `translateX(${rect.width}px)`;\n};\n```",
  'references/performance.md#no-layout-inducing-writes-in-animation-paths':
    "### No layout-inducing writes in animation paths\n\nAvoiding layout reads is only half the contract. Repeated writes to geometry or SVG transform attributes invalidate layout or paint, so the browser must redo that work while the animation runs. This remains true when WAAPI or CSS owns other parts of the timeline.\n\n**Do:** Animate `transform` or `opacity` on an HTML wrapper. A CSS transform directly on an SVG element can also work when its browser support and `transform-box` behavior are verified.\n\n```ts\nwrapper.style.transform = `translate(${x}px, ${y}px) rotate(${angle}deg)`;\n```\n\n**Don't:** Mutate SVG transform lists or geometry every frame.\n\n```ts\nonTick: () => {\n  svgTransform.setTranslate(x, y);\n  path.setAttribute('d', nextPath);\n};\n```\n\nThe same rule applies to repeated CSS layout writes such as `width`, `height`, inset positions, margins, and padding. A one-time write for sizing or layout is legitimate; the costly pattern is writing these properties repeatedly in an animation, pointer-move, or observer path.",
  'references/performance.md#observer-pooling':
    '### Observer pooling\n\nphase pools IntersectionObserver (keyed by serialized options), ResizeObserver (singleton), and MediaQueryList (keyed by query string).\n\nA raw IO/RO finding means only that the code skips the shared pool; it does not prove a leak. Before replacing it, check how many elements it watches, how it uses each observer entry, how elements are removed, and who disconnects it. Replace it only if a phase API supports the same behavior.\n\n**Example to review:**\n\n```ts\n// Creating raw observers outside the pool\nconst io = new IntersectionObserver(callback, options);\nio.observe(element);\n```\n\nUse `createSight`, `createScrollProgress`, `useSize`, or `useMediaQuery` when they provide the same elements and observer data; all use shared pools. Twenty elements with the same IO options share one observer. A raw observer may be simpler for changing element sets or data from each entry. Keep it only if removed elements are unobserved and cleanup disconnects it.\n\nFix or replace observers with missing cleanup, one observer per item, duplicate subscriptions, or simple single-element wiring that a phase API already covers.',
  'references/performance.md#reduced-motion-by-default':
    "### Reduced motion by default\n\nAll phase primitives respect `prefers-reduced-motion: reduce` automatically. Bypassing requires explicit `reducedMotion: 'ignore'`.\n\n**Don't:**\n\n```ts\n// Ignoring reduced motion without justification\ncreateLoop({ target: el, onTick: draw, reducedMotion: 'ignore' });\n```\n\n**Do:** Use `'ignore'` when motion is essential, such as in a data visualization, game, or motion-based accessibility feature. It is also valid when a parent responds to preference changes, does not render the animated child while reduced motion is on, and shows the same information without motion. A one-time check or incomplete fallback does not qualify.",
  'references/performance.md#will-change-only-while-animating':
    "### `will-change` only while animating\n\n`will-change` promotes an element to its own GPU compositing layer, consuming VRAM and preventing the browser from coalescing paint operations. Leaving it on permanently wastes GPU memory when the animation is paused or idle.\n\n**Don't:**\n\n```tsx\n// Permanent GPU layer even when animation is paused or never visible\n<div className=\"will-change-transform\" />\n```\n\n**Do:** Toggle `will-change` based on animation state:\n\n```tsx\n<div className={shouldAnimate ? 'will-change-transform' : ''} />\n```\n\nFor JS-driven animations via `useLoop`, the browser auto-promotes after the first few `style.transform` writes. You typically don't need `will-change` at all. It's primarily useful for CSS `animation` / `transition` where you want to signal the compositor before the animation starts.",
  'references/performance.md#zero-per-frame-allocations':
    "### Zero per-frame allocations\n\nV8's garbage collector runs in stop-the-world bursts on the main thread. Every allocation inside `onTick` becomes GC pressure that directly causes dropped frames. Even small objects accumulate across 60 calls/sec and trigger collections mid-animation. `FrameState` is created once and mutated in place every frame. Your `onTick`/`draw` must match.\n\n**Do:**\n\n```ts\n// Pre-allocate outside the loop\nconst pos = { x: 0, y: 0 };\n\nonTick: (frame) => {\n  pos.x = Math.cos(frame.elapsed * 0.001) * radius;\n  pos.y = Math.sin(frame.elapsed * 0.001) * radius;\n  el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;\n};\n```\n\n**Don't:**\n\n```ts\nonTick: (frame) => {\n  // EVERY ONE OF THESE ALLOCATES:\n  const pos = { x: 0, y: 0 }; // object literal\n  const points = [1, 2, 3]; // array literal\n  const items = arr.map((x) => x * 2); // .map() returns new array\n  const filtered = arr.filter((x) => x > 0); // .filter() returns new array\n  const copy = { ...existing }; // spread operator\n  const msg = `frame ${frame.frame}`; // template literal\n  el.style.transform = fn(); // if fn() creates a closure\n};\n```\n\n**Pragmatic exception:** writing a template literal to `el.style.transform` (as in the Do example above) is acceptable. You must produce a string to set a CSS property, and the browser immediately consumes it. The rule targets unnecessary intermediate allocations (objects, arrays, closures), not the unavoidable final string write to the DOM.",
  'references/rendering-recipes.md#what-not-to-compose':
    "## What not to compose\n\n- **Don't wrap a `Defer` in a `WhenVisible`.** Redundant. `WhenVisible` already withholds the mount until near the viewport, so the `content-visibility` skip never applies. Pick one tier.\n- **Don't reach for `useRenderState` around a phase loop.** `useLoop`/`useCanvas`/`useLifecycle` self-pause off-screen already. Adding it is dead weight.\n- **Don't use `WhenIdle`/`WhenVisible` for SEO-critical content.** Their children are absent from SSR HTML. Use `Defer`.\n- **Don't leave a nonzero final in-flow footprint unreserved.** Match it through the wrapper, parent layout, or fallback. A zero-height fallback is correct when the mounted output also has zero in-flow footprint.\n- **Don't rely on `useSize` or `useContainerQuery` inside a skipped `Defer` subtree.** The CSS Containment spec silences `ResizeObserver` callbacks while `content-visibility: auto` content is skipped. This is spec behavior across all browsers, not a bug. Size observations resume when the element scrolls back into view, but any changes that occurred while skipped are delivered only at that point. Use `useRenderState` to detect the skip/unskip transition if your code depends on it.",
  'references/smil.md#svg-smil-lifecycle-and-reduced-motion':
    '# SVG SMIL lifecycle and reduced motion\n\nKeep SVG SMIL browser-managed when `<animate>`, `<animateMotion>`, or `<animateTransform>` already describes the timeline. Add phase only as the `when` layer: reduced motion chooses static output, and `useLifecycle` controls the owning SVG root.\n\n## Choose the owner\n\n- Keep SMIL for an existing declarative SVG attribute timeline.\n- Use CSS or WAAPI for an HTML transform or opacity timeline.\n- Use `useLoop` only when values depend on live input or simulation state.\n\nReact does no per-frame work in the SMIL branch.\n\n## Core recipe\n\nRender meaningful static SVG attributes outside `<animate*>`. Use `begin="indefinite"` so server output cannot move before client visibility and motion preferences are known. Start once when lifecycle becomes active, then pause or resume the root timeline without restarting it.\n\n```tsx\n\'use client\';\n\nimport { useEffect, useRef } from \'react\';\nimport { useLifecycle, usePrefersReducedMotion } from \'phase/react\';\n\nexport function StatusPulse() {\n  const svgRef = useRef<SVGSVGElement>(null);\n  const animationRef = useRef<SVGAnimateElement>(null);\n  const hasBegunRef = useRef(false);\n  const reducedMotion = usePrefersReducedMotion();\n  const { isActive } = useLifecycle({\n    ref: svgRef,\n    onPhaseChange: (phase) => {\n      if (phase !== \'active\') svgRef.current?.pauseAnimations?.();\n    },\n  });\n\n  useEffect(() => {\n    const svg = svgRef.current;\n    if (\n      !svg ||\n      typeof svg.pauseAnimations !== \'function\' ||\n      typeof svg.unpauseAnimations !== \'function\'\n    ) {\n      return;\n    }\n\n    if (reducedMotion || !isActive) {\n      if (reducedMotion) hasBegunRef.current = false;\n      svg.pauseAnimations();\n      return;\n    }\n\n    svg.unpauseAnimations();\n    const animation = animationRef.current;\n    if (\n      !hasBegunRef.current &&\n      animation &&\n      typeof animation.beginElement === \'function\'\n    ) {\n      animation.beginElement();\n      hasBegunRef.current = true;\n    }\n  }, [isActive, reducedMotion]);\n\n  return (\n    <svg ref={svgRef} viewBox="0 0 24 24" aria-label="Loading">\n      <circle cx="12" cy="12" r="4">\n        {!reducedMotion && (\n          <animate\n            ref={animationRef}\n            attributeName="r"\n            values="4;8;4"\n            begin="indefinite"\n            dur="1.2s"\n            repeatCount="indefinite"\n          />\n        )}\n      </circle>\n    </svg>\n  );\n}\n```\n\n`usePrefersReducedMotion()` returns `false` during SSR and initial hydration. Conditional omission alone therefore cannot prevent first-paint motion from an auto-starting SMIL element; the inert `begin="indefinite"` state closes that gap. If root control is unsupported, the effect leaves this state static.\n\n## Delayed imperative starts\n\nKeep the immediate start above unless existing behavior requires a delayed `beginElement()`. For that branch, schedule the timer only after the root API checks and active-lifecycle checks pass. Extend `onPhaseChange` to clear the timer synchronously, and recheck eligibility when the callback runs:\n\n```tsx\nconst timerRef = useRef<number | null>(null);\nconst playbackAllowedRef = useRef(false);\n\nfunction clearBeginTimer() {\n  if (timerRef.current === null) return;\n  window.clearTimeout(timerRef.current);\n  timerRef.current = null;\n}\n\n// In onPhaseChange:\nplaybackAllowedRef.current = phase === \'active\';\nif (phase !== \'active\') {\n  clearBeginTimer();\n  svgRef.current?.pauseAnimations?.();\n}\n\n// In the active effect, instead of the immediate beginElement() call:\nif (hasBegunRef.current) return;\ntimerRef.current = window.setTimeout(() => {\n  timerRef.current = null;\n  const animation = animationRef.current;\n  if (\n    !playbackAllowedRef.current ||\n    svgRef.current !== svg ||\n    !animation ||\n    typeof animation.beginElement !== \'function\'\n  ) {\n    return;\n  }\n  animation.beginElement();\n  hasBegunRef.current = true;\n}, 600);\nreturn clearBeginTimer;\n```\n\nThe root identity check prevents a stale timer from starting a replacement SVG. `hasBegunRef` prevents pause/resume from scheduling a second start. Effect cleanup handles unmount.\n\n## Compatibility boundary\n\nFeature-detect root pause/resume and imperative start methods. Root pause before begin, position-preserving resume, finite completion, and timer cleanup were verified in Chromium and Firefox. Safari and real background-tab behavior were not verified. Test the product\'s supported browser matrix before claiming parity, and do not depend on the browser pausing background or off-screen SMIL by itself.\n\n## Completion checklist\n\n- Static SVG remains meaningful without `<animate*>`.\n- Server output cannot auto-start before motion preference is known.\n- One SVG root owns pause and resume.\n- Reduced motion omits animation instead of reducing repetitions.\n- Delayed starts are canceled on pause and teardown.\n- Missing root APIs leave output static.\n- React performs no per-frame work.\n- Compatibility claims match retained browser evidence.\n\n## See also\n\n- [useLifecycle](./use-lifecycle.md). Supplies the root active/paused decision\n- [usePrefersReducedMotion](./use-prefers-reduced-motion.md). Reacts to preference changes\n- [timed sequences](./timed-sequences.md). Chooses browser timing before JavaScript timers\n- [audit](./audit.md). Classifies `svg-smil-animation` findings',
  'references/timed-sequences.md#first-choose-who-owns-the-timeline':
    '## First choose who owns the timeline\n\nPrefer browser keyframes when the whole timeline can be described before playback:\n\n- Values depend only on time.\n- Targets and CSS-animatable keyframes are known when the sequence starts.\n- No JavaScript side effect is required on every frame.\n\nUse CSS for static keyframes and WAAPI when keyframes are generated from runtime data or need imperative control. Add `useLifecycle` only to pause/resume playback off-screen and for reduced motion. Use `useLoop` when frames depend on live pointer/scroll data, layout, simulation state, canvas/WebGL, or JS work that keyframes cannot represent.',
  'references/use-media-query.md#when-to-use':
    "## When to use\n\n- Subscribing to viewport-level or device-level media queries reactively.\n- Dark mode detection: `useMediaQuery('(prefers-color-scheme: dark)')`.\n- Reduced motion detection (reactive). Prefer `usePrefersReducedMotion()` for this specific case.\n- Responsive logic that depends on viewport, not element size.",
  'references/use-pointer.md#when-to-use':
    '## When to use\n\n- Custom cursor effects that follow the pointer relative to an element.\n- Canvas interaction where pointer position drives per-frame rendering.\n- Tooltip positioning that reads element bounds without per-event reflow.',
  'references/use-stable-callback.md#when-to-use':
    '## When to use\n\n- Passing callbacks to memoized children without breaking `React.memo`.\n- Using callbacks in effect deps without causing re-runs.\n- Event handlers that need latest closure values but stable identity.',
  'references/use-synced-ref.md#when-to-use':
    '## When to use\n\n- Storing the latest version of a callback for use inside `onTick` / `draw` without restarting effects.\n- Accessing the latest props/state from inside event handlers or effects with empty deps arrays.\n- Internal use: `useLoop` and `useCanvas` use this internally to keep `onTick`/`draw` fresh.',
};
